head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST71001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst71001.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_searchCodeType", fn: function () { return String(String((dma_pageContext.get("searchCodeType") ?? ""))); } },
        { childId: "ipt_langTpCd", fn: function () { return String(String((dma_pageContext.get("langTpCd") ?? ""))); } },
        { childId: "ipt_searchCorpName", fn: function () { return String(String((dma_pageContext.get("searchCorpName") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        $("#ipt_searchCorpName").bind("change", function() {
                $c.util.getComponent('ipt_repIsuSrtCd').setValue("");
        });
        await scwin.fnInit();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
// [저작] 기간 프리셋 버튼 — fnDisplaySearchBtnDates 재설계 (btn_cm 텍스트·gcc date 조합)

