 */
scwin.btn_pd_3m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -3); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71001.pd_3m' }); } };

/**
 * @method
 * @name btn_pd_6m_onclick
 * @description 「6개월」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_6m_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addMonth(to, -6); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71001.pd_6m' }); } };

/**
 * @method
 * @name btn_pd_1y_onclick
 * @description 「1년」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_pd_1y_onclick = function () { try { const to = WebSquare.date.getCurrentServerDate('yyyyMMdd'); const from = $c.date.addYear(to, -1); const f = ($c.util.getComponent('cal_fromDate') || $c.util.getComponent('ipt_fromDate') || $c.util.getComponent('fromDate')); const t = ($c.util.getComponent('cal_toDate') || $c.util.getComponent('ipt_toDate') || $c.util.getComponent('toDate')); if (f && f.setValue) { f.setValue(from); } if (t && t.setValue) { t.setValue(to); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst71001.pd_1y' }); } };

/**
 * @method
 * @name btn_findCompanyName_onclick
 * @description btn_findCompanyName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findCompanyName_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71001.btn_findCompanyName_onclick' }); }
};

/**
 * @method
 * @name ipt_reportNmTmp_onclick
 * @description ipt_reportNmTmp 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_reportNmTmp_onclick = function(e){
    try {
        scwin.openReport(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71001.ipt_reportNmTmp_onclick' }); }
};

/**
 * @method
 * @name btn_findReportName_onclick
 * @description btn_findReportName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findReportName_onclick = function(e){
    try {
        findReportName(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71001.btn_findReportName_onclick' }); }
};

/**
 * @method
 * @name tabDay_onclick
 * @description 「Issues to be delisted」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.tabDay_onclick = function(e){
    try {
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "http://data.krx.co.kr/contents/MDC/MDI/mdiLoader/index.cmd?menuId=MDC0201020202&locale=en", unresolved: "nav:" + "http://data.krx.co.kr/contents/MDC/MDI/mdiLoader/index.cmd?menuId=MDC0201020202&locale=en" }; })();return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71001.tabDay_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71001.btn_fnSearchInit_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst71001.btn_fnDownload_onclick' }); }
};

/**
 * @method
 * @name ipt_dsclsLayerAll_onclick
 * @description ipt_dsclsLayerAll 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_dsclsLayerAll_onclick = function(e){
    try {
        scwin.fnCheckAllDscls()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst71001.ipt_dsclsLayerAll_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/disclosure/marketalertlist.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/disclosure/marketalertlist.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openReport
 * @description open Report 처리
 * @returns {void}
 * @hidden N
 */
scwin.openReport = function () {
    $c.util.getComponent('ipt_reportNmTmp').setValue("");
    findReportName();
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInit = async function () {
    if ($c.util.getComponent('ipt_langTpCd').getValue() === "1") {
        $("#onlyEng").attr('checked', true);
    }
    // 수동 전환 필요: fnDisplaySearchBtnDates(N) / fnDisplaySearchBtnDatesOnlyPeriod(N) → 작업본 dateSetting 관례로 재설계 (조회 기간 프리셋)
    //   KRX 방향: 재설계 축 — 작업본 정답지 관례 = scwin.dateSetting() + 기간 버튼 핸들러(btn_3mon_onclick 등)가 캘린더 setValue 로 기간을 직접 세움(ULDINF05800 계열 실증). 1:1 대체 함수가 없고 속성 승격도 아님 — 조회 영역 저작 관례로 실현. 요청 명부에서 제외(재설계 분류).
    //   근거: catalog/function-map (이 주석은 고쳐 쓴 뒤 지우십시오)
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnDisplaySearchBtnDates( "1 ') */
    await scwin.fnOrder('1', 'D');
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    await scwin.fnOrder('1', 'D');
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearchInit();
        }
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if (!await scwin.fnDisclosureAllSetting()) {
        return;
    }
    if (($c.util.getComponent('ipt_reportNmTmp').getValue() == null ? '' : String($c.util.getComponent('ipt_reportNmTmp').getValue())) === '') {
        $c.util.getComponent('ipt_reportCd').setValue("");
    }
    if (($c.util.getComponent('ipt_reportCd').getValue() == null ? '' : String($c.util.getComponent('ipt_reportCd').getValue())) !== '') {
        (($c.util.getComponent('ipt_reportNmTmp')) && ($c.util.getComponent('ipt_reportNmTmp')).setDisabled ? ($c.util.getComponent('ipt_reportNmTmp')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    }
    if ($("#searchForm").find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $("#searchForm").find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchMarketAlertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "marketAlertList_sub");
    document.searchForm.ajaxSubmit({ ajaxUrl: '/disclosure/marketalertlist.do', ajaxCallBack: scwin.fnSearchCallBack });
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
    $("tr:odd").addClass("active");
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    const searchForm = $('#searchForm');
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("Start Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("End Date that you inserted is incorrect. Please check the date.");
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if (($c.util.getComponent('ipt_reportNmTmp').getValue() == null ? '' : String($c.util.getComponent('ipt_reportNmTmp').getValue())) === '') {
        $c.util.getComponent('ipt_reportCd').setValue("");
    } else {
        (($c.util.getComponent('ipt_reportNmTmp')) && ($c.util.getComponent('ipt_reportNmTmp')).setDisabled ? ($c.util.getComponent('ipt_reportNmTmp')).setDisabled((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchMarketAlertSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "marketAlertList_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnCheckAllDscls
 * @description fn Check All Dscls 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckAllDscls = function () {
    let isCheck = false;
    const allChk = $("#searchForm").find("input:checkbox[name=ipt_dsclsLayerAll]");
    if (allChk.attr("checked") === "checked") {
        isCheck = true;
    }
    $("#searchForm").find("input:checkbox[name=disclosureTypeArr]").each(function() {
            if (isCheck) {
                $(this).attr("checked", "checked");
            } else {
                $(this).removeAttr("checked");
            }
    });
};

/**
 * @method
 * @name fnDisclosureAllSetting
 * @description fn Disclosure All Setting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDisclosureAllSetting = async function () {
    let varCheckSetting = "";
    const setName = $("#searchForm > #disclsTpArr");
    $("#searchForm").find("input:checkbox[name=disclosureTypeArr]").each(function() {
            if ($(this).attr("checked") === "checked") {
                varCheckSetting += $(this).val();
            }
    });
    if (varCheckSetting === "") {
        await $c.win.alert("Please check 'Disclosure Type' at least one.");
        return false;
    } else {
        setName.val(varCheckSetting);
        return true;
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('ipt_searchCorpName').setValue(comAbbrv);
    $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "A" + ipt_repIsuSrtCd);
    $c.util.getComponent("dma_fnDownloadReq").set("searchCodeType", "char");
};

/**
